【主要应用】N 较小（一般 ≤ 20）时的集合选择、棋盘放置、TSP 等问题。
【应用方式】用二进制整数表示集合状态，枚举子集或新加入元素进行转移。常见技巧：预处理合法状态、枚举子集、滚动数组。
【模板代码】
```cpp
// TSP 状压 DP
int f[1 << n][n];
memset(f, 0x3f, sizeof(f));
f[1][0] = 0;
for (int s = 1; s < (1 << n); s++)
    for (int i = 0; i < n; i++) if (s >> i & 1)
        for (int j = 0; j < n; j++) if (!(s >> j & 1))
            f[s | (1 << j)][j] = min(f[s | (1 << j)][j], f[s][i] + dis[i][j]);

// 枚举子集
for (int sub = s; sub; sub = (sub - 1) & s) { /* ... */ }
```

【主要应用】吃奶酪、蒙德里安的梦想、愤怒的小鸟、炮兵阵地、Corn Fields、互不侵犯、No Change、邦邦的大合唱站队、Scarlet的字符串、学校食堂、Bill的挑战、yyy loves Maths VII、一双木棋、中国象棋、寿司晚宴。
【应用方式】棋盘问题按行状压并预处理合法状态；TSP 用 f[s][i]；枚举子集优化集合划分。
【模板代码】
```cpp
// 棋盘状压：预处理合法行状态
vector<int> ok;
for (int s = 0; s < (1 << m); s++)
    if (!(s & (s << 1))) ok.push_back(s);
// 转移
for (int i = 1; i <= n; i++)
    for (int s : ok)
        for (int t : ok)
            if (!(s & t) && check(s, t))
                f[i][s] = max(f[i][s], f[i-1][t] + count(s));
```

【主要应用】石子合并、能量项链、矩阵取数、涂色、字符串折叠等区间划分与合并问题。
【应用方式】以区间长度从小到大枚举，枚举断点 k 合并左右子区间。可用四边形不等式优化到 O(n^2)。
【模板代码】
```cpp
// 区间 DP 基础
for (int len = 2; len <= n; len++)
    for (int l = 1; l + len - 1 <= n; l++) {
        int r = l + len - 1;
        f[l][r] = INF;
        for (int k = l; k < r; k++)
            f[l][r] = min(f[l][r], f[l][k] + f[k+1][r] + cost(l, r));
    }

// 环形区间 DP：断环成链，长度 2n
```

【主要应用】石子合并、Rectangle Painting 1、248 G、能量项链、矩阵取数游戏、涂色、字符串折叠、Sue 的小球、石子合并（弱化版）。
【应用方式】环形问题复制一倍；涂色类问题按颜色块转移；字符串折叠结合 KMP 或枚举重复节。
【模板代码】
```cpp
// 石子合并（环形）
for (int i = 1; i <= 2 * n; i++) sum[i] = sum[i-1] + a[i];
for (int len = 2; len <= n; len++)
    for (int l = 1; l + len - 1 <= 2 * n; l++) {
        int r = l + len - 1;
        f[l][r] = INF;
        for (int k = l; k < r; k++)
            f[l][r] = min(f[l][r], f[l][k] + f[k+1][r] + sum[r] - sum[l-1]);
    }
int ans = INF;
for (int i = 1; i <= n; i++) ans = min(ans, f[i][i + n - 1]);
```

【主要应用】树上选择、依赖背包、树形结构统计、换根 DP。
【应用方式】后序遍历，先处理子树再合并到父节点。常见状态 f[u][0/1] 表示选或不选；树形背包用 size 优化。
【模板代码】
```cpp
// 树形 DP 基础
void dfs(int u, int fa) {
    f[u][0] = 0; f[u][1] = w[u];
    for (int v : g[u]) {
        if (v == fa) continue;
        dfs(v, u);
        f[u][0] += max(f[v][0], f[v][1]);
        f[u][1] += f[v][0];
    }
}

// 树形背包
void dfs(int u, int fa) {
    sz[u] = 1;
    for (int v : g[u]) {
        if (v == fa) continue;
        dfs(v, u);
        for (int j = min(m, sz[u]); j >= 0; j--)
            for (int k = 0; k <= min(sz[v], m - j); k++)
                f[u][j + k] = max(f[u][j + k], f[u][j] + f[v][k]);
        sz[u] += sz[v];
    }
}
```

【主要应用】加分二叉树、二叉苹果树、没有上司的舞会、最佳团体、最大子树和、有线电视网、选课、三色二叉树、Nearby Cows、小Q的棋盘、括号树、骑士、树上染色、Gem 气垫车、潜入行动。
【应用方式】树形背包注意倒序枚举；基环树先断环再树形 DP；换根 DP 用两次 dfs。
【模板代码】
```cpp
// 换根 DP
void dfs1(int u, int fa) {
    sz[u] = 1;
    for (int v : g[u]) if (v != fa) {
        dfs1(v, u);
        sz[u] += sz[v];
        f[u] += f[v] + sz[v];
    }
}
void dfs2(int u, int fa) {
    for (int v : g[u]) if (v != fa) {
        f[v] = f[u] - sz[v] + (n - sz[v]);
        dfs2(v, u);
    }
}
```

【主要应用】对朴素 DP 进行时间或空间上的优化，如滚动数组、前缀和、树状数组、线段树等。
【应用方式】观察转移方程的依赖范围，用数据结构维护最值或前缀和，降低一维复杂度。
【模板代码】
```cpp
// 树状数组维护前缀最值
void update(int x, int v) {
    for (; x <= n; x += x & -x) bit[x] = max(bit[x], v);
}
int query(int x) {
    int res = 0;
    for (; x; x -= x & -x) res = max(res, bit[x]);
    return res;
}
```

【主要应用】方伯伯的玉米田、基站选址。
【应用方式】用树状数组或线段树维护转移前缀最值；滚动数组压缩空间。
【模板代码】
```cpp
// 滚动数组
for (int i = 1; i <= n; i++)
    for (int j = m; j >= 0; j--)
        f[j] = max(f[j], f[j - w[i]] + v[i]);
```

【主要应用】转移方程形如 f[i] = max/min(f[j] + cost) 且 j 的可行区间随 i 单调移动时，用单调队列优化到 O(n)。
【应用方式】维护一个双端队列，保证队首是最优决策，队内值单调；每次加入新决策前弹出劣质决策。
【模板代码】
```cpp
// 单调队列优化 DP
deque<int> q;
for (int i = 1; i <= n; i++) {
    while (!q.empty() && q.front() < i - k) q.pop_front();
    f[i] = f[q.front()] + a[i];
    while (!q.empty() && f[q.back()] >= f[i]) q.pop_back();
    q.push_back(i);
}
```

【主要应用】Mowing the Lawn、宝物筛选、琪露诺、跳房子、Pogo-Cow、PTA-Little Bird、TEM-Temperature、Buying Feed、划分、NOI 嘉年华、股票交易、yyf hates choukapai。
【应用方式】先写出朴素转移，确定决策区间单调性；用 deque 维护最优决策；多重背包也可用单调队列优化。
【模板代码】
```cpp
// 多重背包单调队列优化
for (int i = 1; i <= n; i++)
    for (int r = 0; r < w[i]; r++) {
        deque<int> q;
        for (int j = r; j <= m; j += w[i]) {
            while (!q.empty() && q.front() < j - c[i] * w[i]) q.pop_front();
            if (!q.empty()) f[j] = max(f[j], f[q.front()] + (j - q.front()) / w[i] * v[i]);
            while (!q.empty() && f[q.back()] <= f[j]) q.pop_back();
            q.push_back(j);
        }
    }
```

【主要应用】转移方程可化为 f[i] = min/max(f[j] + a[i]*b[j] + c[i] + d[j]) 形式，且斜率单调时使用。
【应用方式】将转移方程变形为 y = kx + b 的形式，用单调队列维护下凸壳或上凸壳；若斜率不单调，可用二分或李超线段树。
【模板代码】
```cpp
// 斜率优化（下凸壳）
int h = 1, t = 0;
for (int i = 1; i <= n; i++) {
    while (h < t && slope(q[h], q[h+1]) <= k[i]) h++;
    f[i] = f[q[h]] + a[i] * q[h] + b[i];
    while (h < t && slope(q[t-1], q[t]) >= slope(q[t], i)) t--;
    q[++t] = i;
}
```

【主要应用】Land Acquisition、特别行动队、锯木厂选址、序列分割、回家路线、购票、玩具装箱、征途。
【应用方式】先写出 DP 方程，整理成 y = kx + b；用单调队列或二分维护凸壳；注意斜率单调性与精度。
【模板代码】
```cpp
// 玩具装箱（斜率优化）
double slope(int i, int j) {
    return (f[i] + sq(i) - f[j] - sq(j)) / (2.0 * (i - j));
}
for (int i = 1; i <= n; i++) {
    while (h < t && slope(q[h], q[h+1]) <= sum[i]) h++;
    f[i] = f[q[h]] + sq(sum[i] - sum[q[h]] - L);
    while (h < t && slope(q[t-1], q[t]) >= slope(q[t], i)) t--;
    q[++t] = i;
}
```

【主要应用】区间 DP 中 cost 满足四边形不等式与区间包含单调性时，决策点单调，可优化到 O(n^2)。
【应用方式】证明或验证四边形不等式；用 opt[l][r-1] <= opt[l][r] <= opt[l+1][r] 缩小 k 的枚举范围。
【模板代码】
```cpp
// 四边形不等式优化区间 DP
for (int len = 2; len <= n; len++)
    for (int l = 1; l + len - 1 <= n; l++) {
        int r = l + len - 1;
        f[l][r] = INF;
        for (int k = opt[l][r-1]; k <= opt[l+1][r]; k++)
            if (f[l][r] > f[l][k] + f[k+1][r] + cost(l, r)) {
                f[l][r] = f[l][k] + f[k+1][r] + cost(l, r);
                opt[l][r] = k;
            }
    }
```

【主要应用】石子合并、诗人小G、邮局加强版、最优二叉搜索树、征途。
【应用方式】先验证代价函数满足四边形不等式；用决策单调性缩小 k 枚举范围；也可用于 1D/1D DP 的分治优化。
【模板代码】
```cpp
// 分治优化 1D/1D DP
void solve(int l, int r, int ql, int qr) {
    if (l > r) return;
    int mid = (l + r) >> 1, pos = ql;
    for (int k = ql; k <= min(qr, mid); k++)
        if (f[mid] > g[k] + cost(k, mid)) {
            f[mid] = g[k] + cost(k, mid);
            pos = k;
        }
    solve(l, mid - 1, ql, pos);
    solve(mid + 1, r, pos, qr);
}
```
